[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>CommerceForge Dev Docs</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg-primary: #0d1117;
      --bg-secondary: #161b22;
      --bg-card: #1a2030;
      --bg-elevated: #21262d;
      --border: #30363d;
      --border-subtle: #21262d;
      --text-primary: #e6edf3;
      --text-secondary: #8b949e;
      --text-muted: #6e7681;
      --accent: #475F91;
      --accent-hover: #5a74ad;
      --accent-bright: #58a6ff;
      --green: #3fb950;
      --cyan: #39d0d8;
      --radius: 8px;
      --radius-lg: 12px;
      --font-mono: 'JetBrains Mono', 'Fira Code', monospace;
      --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
    }

    html { scroll-behavior: smooth; }
    body {
      font-family: var(--font-sans);
      background: var(--bg-primary);
      color: var(--text-primary);
      line-height: 1.6;
      min-height: 100vh;
    }

    a { color: var(--accent-bright); text-decoration: none; transition: color 0.15s; }
    a:hover { color: var(--accent-hover); }

    /* NAV */
    .nav {
      position: sticky; top: 0; z-index: 100;
      background: rgba(13,17,23,0.92);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border);
      padding: 0 24px;
    }
    .nav-inner {
      max-width: 1200px; margin: 0 auto;
      display: flex; align-items: center;
      height: 60px; gap: 0;
    }
    .nav-logo {
      font-weight: 700; font-size: 16px;
      color: var(--text-primary);
      display: flex; align-items: center; gap: 8px;
      margin-right: 40px; white-space: nowrap;
      text-decoration: none;
    }
    .nav-logo-icon {
      width: 28px; height: 28px; border-radius: 6px;
      background: linear-gradient(135deg, var(--accent) 0%, var(--cyan) 100%);
      display: flex; align-items: center; justify-content: center;
      font-size: 14px; font-weight: 800; color: #fff;
      flex-shrink: 0;
    }
    .nav-links { display: flex; gap: 4px; flex: 1; }
    .nav-link {
      padding: 6px 12px; border-radius: 6px;
      font-size: 14px; font-weight: 500;
      color: var(--text-secondary);
      text-decoration: none;
      transition: color 0.15s, background 0.15s;
    }
    .nav-link:hover { color: var(--text-primary); background: var(--bg-elevated); }
    .nav-link.active { color: var(--text-primary); }
    .nav-actions { display: flex; align-items: center; gap: 8px; margin-left: auto; }
    .nav-search {
      display: flex; align-items: center; gap: 8px;
      background: var(--bg-secondary);
      border: 1px solid var(--border);
      border-radius: 6px; padding: 6px 12px;
      font-size: 13px; color: var(--text-muted);
      cursor: pointer; transition: border-color 0.15s;
      white-space: nowrap;
    }
    .nav-search:hover { border-color: var(--accent); color: var(--text-secondary); }
    .nav-search svg { width: 14px; height: 14px; }
    .btn-login {
      padding: 6px 14px; border-radius: 6px;
      background: var(--bg-elevated);
      border: 1px solid var(--border);
      font-size: 13px; font-weight: 500;
      color: var(--text-primary);
      cursor: pointer; transition: all 0.15s;
      text-decoration: none;
    }
    .btn-login:hover { background: var(--bg-card); border-color: var(--accent); color: var(--accent-bright); }
    .nav-hamburger {
      display: none; background: none; border: none;
      cursor: pointer; padding: 6px; color: var(--text-secondary);
    }

    /* HERO */
    .hero {
      background: radial-gradient(ellipse 80% 60% at 50% -10%, rgba(71,95,145,0.25) 0%, transparent 70%),
                  var(--bg-primary);
      padding: 80px 24px 72px;
      text-align: center;
    }
    .hero-badge {
      display: inline-flex; align-items: center; gap: 6px;
      background: rgba(71,95,145,0.15); border: 1px solid rgba(71,95,145,0.35);
      padding: 4px 12px; border-radius: 20px;
      font-size: 12px; font-weight: 600; color: var(--accent-bright);
      text-transform: uppercase; letter-spacing: 0.08em;
      margin-bottom: 24px;
    }
    .hero h1 {
      font-size: clamp(32px, 6vw, 56px);
      font-weight: 700; line-height: 1.15;
      color: var(--text-primary);
      max-width: 700px; margin: 0 auto 20px;
      letter-spacing: -0.02em;
    }
    .hero h1 span { color: var(--cyan); }
    .hero-sub {
      font-size: 17px; color: var(--text-secondary);
      max-width: 600px; margin: 0 auto 40px;
      line-height: 1.7;
    }
    .hero-ctas { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }
    .btn-primary {
      padding: 10px 22px; border-radius: var(--radius);
      background: var(--accent);
      border: 1px solid var(--accent);
      font-size: 14px; font-weight: 600;
      color: #fff; cursor: pointer;
      transition: all 0.15s;
      text-decoration: none; display: inline-block;
    }
    .btn-primary:hover { background: var(--accent-hover); border-color: var(--accent-hover); color: #fff; }
    .btn-outline {
      padding: 10px 22px; border-radius: var(--radius);
      background: transparent;
      border: 1px solid var(--border);
      font-size: 14px; font-weight: 600;
      color: var(--text-primary); cursor: pointer;
      transition: all 0.15s;
      text-decoration: none; display: inline-block;
    }
    .btn-outline:hover { border-color: var(--accent); color: var(--accent-bright); }

    /* SECTIONS */
    .section { padding: 72px 24px; }
    .section-inner { max-width: 1200px; margin: 0 auto; }
    .section-alt { background: var(--bg-secondary); }

    .section-label {
      font-size: 11px; font-weight: 700;
      text-transform: uppercase; letter-spacing: 0.12em;
      color: var(--accent-bright); margin-bottom: 12px;
    }
    .section-title {
      font-size: clamp(22px, 3.5vw, 32px);
      font-weight: 700; line-height: 1.2;
      letter-spacing: -0.02em; margin-bottom: 12px;
    }
    .section-sub {
      font-size: 16px; color: var(--text-secondary);
      max-width: 640px; line-height: 1.7;
    }
    .section-header { margin-bottom: 48px; }

    /* PRODUCT CARDS */
    .product-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
    .product-card {
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 32px; position: relative; overflow: hidden;
      transition: border-color 0.2s, transform 0.2s;
      display: flex; flex-direction: column;
    }
    .product-card::before {
      content: ''; position: absolute;
      top: 0; left: 0; right: 0; height: 2px;
      opacity: 0; transition: opacity 0.2s;
    }
    .product-card.apps::before { background: linear-gradient(90deg, var(--accent), var(--cyan)); }
    .product-card.storefronts::before { background: linear-gradient(90deg, var(--cyan), var(--green)); }
    .product-card.agents::before { background: linear-gradient(90deg, #a371f7, var(--accent)); }
    .product-card:hover { border-color: var(--accent); transform: translateY(-2px); }
    .product-card:hover::before { opacity: 1; }
    .card-icon {
      width: 44px; height: 44px; border-radius: 10px;
      display: flex; align-items: center; justify-content: center;
      margin-bottom: 20px; font-size: 20px;
    }
    .apps .card-icon { background: rgba(71,95,145,0.2); }
    .storefronts .card-icon { background: rgba(57,208,216,0.15); }
    .agents .card-icon { background: rgba(163,113,247,0.15); }
    .card-title {
      font-size: 18px; font-weight: 700;
      margin-bottom: 10px; color: var(--text-primary);
    }
    .card-desc {
      font-size: 14px; color: var(--text-secondary);
      line-height: 1.6; flex: 1; margin-bottom: 24px;
    }
    .card-link {
      font-size: 14px; font-weight: 600;
      color: var(--accent-bright);
      display: inline-flex; align-items: center; gap: 6px;
      transition: gap 0.15s;
    }
    .card-link:hover { gap: 10px; color: var(--accent-bright); }

    /* CLI SECTION */
    .cli-layout { display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: start; }
    .cli-left {}
    .cli-right {}

    .accordion-list { display: flex; flex-direction: column; gap: 8px; margin-bottom: 32px; }
    .accordion-item {
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      overflow: hidden; transition: border-color 0.2s;
    }
    .accordion-item.open { border-color: var(--accent); }
    .accordion-trigger {
      width: 100%; padding: 16px 20px;
      display: flex; align-items: center; justify-content: space-between;
      background: none; border: none; cursor: pointer;
      color: var(--text-primary); font-family: var(--font-sans);
      font-size: 15px; font-weight: 600; text-align: left;
      transition: background 0.15s;
    }
    .accordion-trigger:hover { background: var(--bg-elevated); }
    .accordion-chevron {
      width: 18px; height: 18px; color: var(--text-muted);
      transition: transform 0.2s;
    }
    .accordion-item.open .accordion-chevron { transform: rotate(180deg); }
    .accordion-body {
      max-height: 0; overflow: hidden;
      transition: max-height 0.3s ease;
    }
    .accordion-body-inner { padding: 0 20px 20px; }
    .accordion-steps { list-style: none; counter-reset: steps; }
    .accordion-steps li {
      counter-increment: steps;
      display: flex; gap: 14px; align-items: flex-start;
      font-size: 14px; color: var(--text-secondary);
      margin-bottom: 10px; line-height: 1.5;
    }
    .accordion-steps li::before {
      content: counter(steps);
      min-width: 22px; height: 22px; border-radius: 50%;
      background: var(--bg-elevated); border: 1px solid var(--border);
      font-size: 12px; font-weight: 700; color: var(--accent-bright);
      display: flex; align-items: center; justify-content: center;
      flex-shrink: 0; margin-top: 1px;
    }

    /* Code Block */
    .code-block {
      background: #010409;
      border: 1px solid var(--border);
      border-radius: var(--radius);
      overflow: hidden;
    }
    .code-tabs {
      display: flex; gap: 0;
      border-bottom: 1px solid var(--border);
      background: var(--bg-secondary);
      padding: 0 4px;
    }
    .code-tab {
      padding: 8px 16px;
      font-size: 13px; font-weight: 500;
      color: var(--text-muted);
      background: none; border: none;
      border-bottom: 2px solid transparent;
      cursor: pointer; transition: all 0.15s;
      font-family: var(--font-mono);
      margin-bottom: -1px;
    }
    .code-tab:hover { color: var(--text-primary); }
    .code-tab.active { color: var(--accent-bright); border-bottom-color: var(--accent-bright); }
    .code-content { padding: 20px; }
    .code-label {
      font-size: 11px; color: var(--text-muted);
      text-transform: uppercase; letter-spacing: 0.08em;
      margin-bottom: 8px; font-family: var(--font-mono);
    }
    .code-line {
      font-family: var(--font-mono);
      font-size: 14px; color: #e6edf3;
      line-height: 1.6;
      display: flex; align-items: center; gap: 10px;
    }
    .code-line .prompt { color: var(--green); }
    .code-panel { display: none; }
    .code-panel.active { display: block; }
    .code-init-line {
      margin-top: 16px; padding-top: 16px;
      border-top: 1px solid var(--border-subtle);
    }

    /* LAUNCH CTA */
    .launch-cards { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
    .launch-card {
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 32px;
      display: flex; flex-direction: column; gap: 16px;
      transition: border-color 0.2s;
    }
    .launch-card:hover { border-color: var(--accent); }
    .launch-card-icon {
      width: 40px; height: 40px; border-radius: 8px;
      background: rgba(71,95,145,0.2);
      display: flex; align-items: center; justify-content: center;
      font-size: 18px;
    }
    .launch-card h3 { font-size: 18px; font-weight: 700; }
    .launch-card p { font-size: 14px; color: var(--text-secondary); line-height: 1.6; flex: 1; }

    /* COMMUNITY */
    .community-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }
    .community-card {
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 24px 20px;
      display: flex; flex-direction: column; gap: 12px;
      transition: border-color 0.2s, transform 0.2s;
      text-decoration: none;
    }
    .community-card:hover { border-color: var(--accent); transform: translateY(-2px); }
    .community-card-icon { font-size: 22px; }
    .community-card h4 {
      font-size: 14px; font-weight: 700;
      color: var(--text-primary); line-height: 1.3;
    }
    .community-card p { font-size: 13px; color: var(--text-secondary); line-height: 1.5; flex: 1; }
    .community-card-arrow { font-size: 12px; color: var(--accent-bright); font-weight: 600; margin-top: auto; }

    /* FOOTER */
    footer {
      background: var(--bg-secondary);
      border-top: 1px solid var(--border);
      padding: 48px 24px 32px;
    }
    .footer-inner { max-width: 1200px; margin: 0 auto; }
    .footer-top {
      display: grid; grid-template-columns: 200px repeat(3, 1fr);
      gap: 40px; margin-bottom: 40px;
    }
    .footer-brand { }
    .footer-brand-name {
      font-weight: 700; font-size: 15px;
      display: flex; align-items: center; gap: 8px;
      margin-bottom: 10px;
    }
    .footer-brand p { font-size: 13px; color: var(--text-muted); line-height: 1.5; }
    .footer-col h5 {
      font-size: 12px; font-weight: 700;
      text-transform: uppercase; letter-spacing: 0.08em;
      color: var(--text-muted); margin-bottom: 14px;
    }
    .footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 8px; }
    .footer-col ul li a {
      font-size: 13px; color: var(--text-secondary);
      text-decoration: none; transition: color 0.15s;
    }
    .footer-col ul li a:hover { color: var(--text-primary); }
    .footer-bottom {
      border-top: 1px solid var(--border);
      padding-top: 24px;
      display: flex; justify-content: space-between; align-items: center;
      flex-wrap: wrap; gap: 12px;
    }
    .footer-bottom p { font-size: 12px; color: var(--text-muted); }

    @media (max-width: 1024px) {
      .product-cards { grid-template-columns: 1fr 1fr; }
      .cli-layout { grid-template-columns: 1fr; gap: 40px; }
      .community-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-top { grid-template-columns: 1fr 1fr; }
    }
    @media (max-width: 768px) {
      .nav-links { display: none; }
      .nav-hamburger { display: flex; }
      .product-cards { grid-template-columns: 1fr; }
      .launch-cards { grid-template-columns: 1fr; }
      .community-grid { grid-template-columns: 1fr 1fr; }
      .footer-top { grid-template-columns: 1fr 1fr; }
      .hero { padding: 56px 20px 56px; }
      .section { padding: 52px 20px; }
    }
    @media (max-width: 480px) {
      .community-grid { grid-template-columns: 1fr; }
      .footer-top { grid-template-columns: 1fr; }
      .hero-ctas { flex-direction: column; align-items: stretch; text-align: center; }
    }
  </style>
</head>
<body>

<!-- NAV -->
<nav class="nav" aria-label="Main navigation">
  <div class="nav-inner">
    <a href="index.html" class="nav-logo">
      <div class="nav-logo-icon">CF</div>
      CommerceForge
    </a>
    <div class="nav-links" role="list">
      <a href="apps-build.html" class="nav-link" role="listitem">Apps</a>
      <a href="storefronts.html" class="nav-link" role="listitem">Storefronts</a>
      <a href="agents.html" class="nav-link" role="listitem">Agents</a>
      <a href="#" class="nav-link" role="listitem">References</a>
      <a href="support.html" class="nav-link" role="listitem">Help</a>
    </div>
    <div class="nav-actions">
      <div class="nav-search" role="search" aria-label="Search docs">
        <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="6.5" cy="6.5" r="4.5"/><path d="M10.5 10.5l3 3"/></svg>
        Ask assistant
      </div>
      <a href="#" class="btn-login">Log in</a>
      <button class="nav-hamburger" aria-label="Open menu">
        <svg width="20" height="20" viewBox="0 0 20 20" fill="currentColor"><path fill-rule="evenodd" d="M3 5h14v1.5H3V5zm0 4.25h14v1.5H3v-1.5zM3 13.5h14V15H3v-1.5z"/></svg>
      </button>
    </div>
  </div>
</nav>

<!-- HERO -->
<section class="hero" aria-labelledby="hero-title">
  <div class="hero-badge">Developer Platform</div>
  <h1 id="hero-title">CommerceForge<br /><span>Dev Docs</span></h1>
  <p class="hero-sub">Learn how to build an app, or customize your storefront. Whether you're just getting started, deep in the development process, or ready to distribute and monetize your work, CommerceForge's docs, dev tools and frameworks make building easy and efficient.</p>
  <div class="hero-ctas">
    <a href="apps-build.html" class="btn-primary">Build your first app →</a>
    <a href="storefronts.html" class="btn-outline">Build a storefront →</a>
    <a href="agents.html" class="btn-outline">Build agents with UCP →</a>
  </div>
</section>

<!-- PRODUCT CARDS -->
<section class="section section-alt" aria-labelledby="products-title">
  <div class="section-inner">
    <div class="section-header">
      <div class="section-label">Platform</div>
      <h2 class="section-title" id="products-title">Build for every commerce use case</h2>
      <p class="section-sub">Three product pillars to extend, customize, and power commerce experiences at any scale.</p>
    </div>
    <div class="product-cards">
      <div class="product-card apps">
        <div class="card-icon">🧩</div>
        <div class="card-title">Apps</div>
        <p class="card-desc">Extend CommerceForge's core functionality with apps that integrate into the admin, online store, checkout and more. All UI surfaces share Polaris, CommerceForge's unified design system.</p>
        <a href="apps-build.html" class="card-link">Build your first app →</a>
      </div>
      <div class="product-card storefronts">
        <div class="card-icon">🛍️</div>
        <div class="card-title">Storefronts</div>
        <p class="card-desc">Help merchants express their unique brand by building a custom theme or Hydrogen storefront. Full-stack control with advanced commerce APIs and edge delivery.</p>
        <a href="storefronts.html" class="card-link">Build a storefront →</a>
      </div>
      <div class="product-card agents">
        <div class="card-icon">🤖</div>
        <div class="card-title">Agents</div>
        <p class="card-desc">Build agentic shopping experiences powered by CommerceForge merchants, from product discovery to checkout. Leverage Universal Commerce Protocol (UCP) with MCP servers.</p>
        <a href="agents.html" class="card-link">Build agents with UCP →</a>
      </div>
    </div>
  </div>
</section>

<!-- CLI SETUP -->
<section class="section" aria-labelledby="cli-title">
  <div class="section-inner">
    <div class="cli-layout">
      <div class="cli-left">
        <div class="section-label">CLI 3.0</div>
        <h2 class="section-title" id="cli-title">Accelerate development with CommerceForge CLI 3.0</h2>
        <p class="section-sub" style="margin-bottom:36px;">Initialize new apps, themes, and headless storefronts in an instant. A single command installs all the dependencies you need, including the CLI itself, so you can dive straight into development.</p>

        <div class="accordion-list" role="list" aria-label="CLI quick-start guides">

          <div class="accordion-item open" id="acc-apps" role="listitem">
            <button class="accordion-trigger" aria-expanded="true" aria-controls="acc-apps-body" onclick="toggleAccordion('acc-apps')">
              Apps
              <svg class="accordion-chevron" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M4 6l4 4 4-4"/></svg>
            </button>
            <div class="accordion-body" id="acc-apps-body" role="region">
              <div class="accordion-body-inner">
                <ol class="accordion-steps" aria-label="Steps to create an app">
                  <li>Install CommerceForge CLI globally.</li>
                  <li>Navigate to the directory where you want to create your app.</li>
                  <li>Run the command to create a new app. Your app will be added as a new subdirectory.</li>
                </ol>
              </div>
            </div>
          </div>

          <div class="accordion-item" id="acc-themes" role="listitem">
            <button class="accordion-trigger" aria-expanded="false" aria-controls="acc-themes-body" onclick="toggleAccordion('acc-themes')">
              Themes
              <svg class="accordion-chevron" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M4 6l4 4 4-4"/></svg>
            </button>
            <div class="accordion-body" id="acc-themes-body" role="region">
              <div class="accordion-body-inner">
                <ol class="accordion-steps" aria-label="Steps to create a theme">
                  <li>Install CommerceForge CLI globally.</li>
                  <li>Navigate to the directory where you want to create your theme.</li>
                  <li>Run the command to clone a starter theme. Your theme will be created in a new subdirectory.</li>
                </ol>
              </div>
            </div>
          </div>

          <div class="accordion-item" id="acc-headless" role="listitem">
            <button class="accordion-trigger" aria-expanded="false" aria-controls="acc-headless-body" onclick="toggleAccordion('acc-headless')">
              Headless storefronts
              <svg class="accordion-chevron" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M4 6l4 4 4-4"/></svg>
            </button>
            <div class="accordion-body" id="acc-headless-body" role="region">
              <div class="accordion-body-inner">
