<script>
  // Accordion — only one open at a time
  const initCommands = {
    'acc-apps': { label: 'Init app', cmd: 'commerceforge app init' },
    'acc-themes': { label: 'Init theme', cmd: 'commerceforge theme init' },
    'acc-headless': { label: 'Init storefront', cmd: 'commerceforge hydrogen init' }
  };

  function toggleAccordion(id) {
    const items = document.querySelectorAll('.accordion-item');
    items.forEach(item => {
      const body = item.querySelector('.accordion-body');
      const trigger = item.querySelector('.accordion-trigger');
      if (item.id === id) {
        const isOpen = item.classList.contains('open');
        if (!isOpen) {
          item.classList.add('open');
          body.style.maxHeight = body.scrollHeight + 'px';
          trigger.setAttribute('aria-expanded', 'true');
          updateInitCommand(id);
        } else {
          item.classList.remove('open');
          body.style.maxHeight = '0';
          trigger.setAttribute('aria-expanded', 'false');
        }
      } else {
        item.classList.remove('open');
        body.style.maxHeight = '0';
        trigger.setAttribute('aria-expanded', 'false');
      }
    });
  }

  function updateInitCommand(accId) {
    const data = initCommands[accId];
    if (!data) return;
    ['npm','yarn','pnpm'].forEach(pkg => {
      const label = document.getElementById('init-label-' + pkg);
      const cmd = document.getElementById('init-cmd-' + pkg);
      if (label) label.textContent = data.label;
      if (cmd) cmd.innerHTML = '<span class="prompt">$</span> ' + data.cmd;
    });
  }

  // Initialize first accordion open
  (function() {
    const first = document.querySelector('.accordion-item.open');
    if (first) {
      const body = first.querySelector('.accordion-body');
      body.style.maxHeight = body.scrollHeight + 'px';
    }
  })();

  // Package manager tabs
  function switchTab(pkg) {
    document.querySelectorAll('.code-tab').forEach(t => {
      t.classList.remove('active');
      t.setAttribute('aria-selected', 'false');
    });
    document.querySelectorAll('.code-panel').forEach(p => p.classList.remove('active'));

    const tab = document.getElementById('tab-' + pkg);
    const panel = document.getElementById('panel-' + pkg);
    if (tab) { tab.classList.add('active'); tab.setAttribute('aria-selected', 'true'); }
    if (panel) panel.classList.add('active');
  }
</script>
